import boto3
import os

def conditional_update_document(
    table_name: str,
    document_id: str,
    update_data: dict,
    condition_attribute: str,
    condition_value: str
) -> dict:
<GAP>
    dynamodb = boto3.client(
        'dynamodb',
        region_name=os.getenv("AWS_REGION", "us-east-1"), # Default region if not set
        aws_access_key_id=os.getenv("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.getenv("AWS_SECRET_ACCESS_KEY")
    )

    # Construct the UpdateExpression and ExpressionAttributeValues
    update_expression_parts = []
    expression_attribute_values = {}
    expression_attribute_names = {}
    for i, (key, value) in enumerate(update_data.items()):
        update_expression_parts.append(f"#{key} = :new_{key}")
        expression_attribute_values[f":new_{key}"] = {"S": value} # Assuming string type for simplicity
        expression_attribute_names[f"#{key}"] = key

    update_expression = "SET " + ", ".join(update_expression_parts)

    # Add the condition to the ExpressionAttributeValues and Names
    expression_attribute_values[f":current_{condition_attribute}"] = {"S": condition_value}
    expression_attribute_names[f"#{condition_attribute}"] = condition_attribute

    try:
        response = dynamodb.update_item(
            TableName=table_name,
            Key={
                'id': {'S': document_id} # Assuming 'id' is the primary key
            },
            UpdateExpression=update_expression,
            ConditionExpression=f"#{condition_attribute} = :current_{condition_attribute}",
            ExpressionAttributeValues=expression_attribute_values,
            ExpressionAttributeNames=expression_attribute_names,
            ReturnValues='ALL_NEW'
        )
        return {
            "status": "success",
            "updated_attributes": response.get('Attributes')
        }
    except dynamodb.exceptions.ConditionalCheckFailedException:
        return {
            "status": "failed",
            "message": f"Conditional check failed: '{condition_attribute}' was not '{condition_value}' or item does not exist."
        }
    except Exception as e:
        return {
            "status": "error",
            "message": str(e)
        }
